import{z as i,x as l,o as A,c as p,q as r,j as s,D as t,d as E,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"多租户与命名空间策略","description":"","frontmatter":{"title":"多租户与命名空间策略","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-multitenant-policy.md","filePath":"cs/orch-multitenant-policy.md","lastUpdated":1791063341000}'),d={name:"cs/orch-multitenant-policy.md"};function c(u,a,C,m,D,h){const o=l("Mermaid");return A(),p("div",null,[a[2]||(a[2]=r('<h1 id="多租户与命名空间策略" tabindex="-1">多租户与命名空间策略 <a class="header-anchor" href="#多租户与命名空间策略" aria-label="Permalink to &quot;多租户与命名空间策略&quot;">​</a></h1><div class="epigraph"><p>命名空间把名字分成几段、把账本分成几本，却从不把内核分成几份；它是行政边界，别当防火墙用。</p><footer>—— 据 Kubernetes 官方文档（Namespace、ResourceQuota、RBAC）整理</footer></div><p><a href="/cs/orch-resource-qos">上一课</a>把单容器的承诺与上限编译成内核参数；本课问组织维度：几十个团队共享一个集群，谁能在哪个范围创建什么、花多少、误操作时伤多大。namespace 是这个问题的答案单位。安全边界已在 <a href="/cs/virt-security-boundary">虚拟化的安全边界</a> 与 <a href="/cs/container-escape">容器逃逸</a> 收束：共享内核不是隔离档，租户互打要换后端；本课只管行政面——范围、配额、授权。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无约束的共享集群死于三件事：对象与资源总量失控（忘了删的实验负载常驻）、误删与越权（人人都拿管理员令牌）、成本不可归因（没人知道自己团队烧了多少）。</p><p><span class="marginnote">术语翻译：namespace 就是把一个大集群分成几间合租房的手段——房租各记各的账（ResourceQuota）、门锁各配各的钥匙（RBAC）、房号各编各的段（名字唯一）；但水电管线还是共用的（内核与网络），所以隔壁漏水你照样遭殃。</span>缺口是把「范围」钉成一个坐标，让配额、权限、默认值都能挂上去。没有这个坐标，上一课的 request/limit 只能逐个手工填，填漏一个 BestEffort 就漏一本账。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>namespace 提供三样东西，都是<strong>作用域</strong>。名字的作用域：对象名段内唯一，不同团队的 <code>web</code> 互不踩。配额的作用域：ResourceQuota 给段设总量账——CPU 与内存的 request 总额、对象个数上限；校验发生在准入时，超了同步拒绝，而不是事后清理。授权的作用域：RBAC 把角色绑定到段，判定发生在 API 之前的一环——能改 Deployments 不等于能改集群级对象。补上第四件事 LimitRange：给段内没写 requests 的 pod 填默认值，否则零 request 的 pod 绕过所有记账。</p>',8)),(A(),s(n,null,{default:t(()=>[B(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%88%9B%E5%BB%BA%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20AUTHN%5B%22%E8%AE%A4%E8%AF%81%3A%20%E4%BD%A0%E6%98%AF%E8%B0%81%22%5D%0A%20%20AUTHN%20--%3E%20AUTHZ%5B%22RBAC%3A%20%E6%AD%A4%E6%AE%B5%E5%86%85%E8%83%BD%E5%81%9A%E4%BB%80%E4%B9%88%22%5D%0A%20%20AUTHZ%20--%3E%20ADM%5B%22%E5%87%86%E5%85%A5%3A%20quota%20%E4%B8%8E%20limitrange%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20ADM%20--%3E%7C%22%E8%B6%85%E8%B4%A6%E6%9C%AC%22%7C%20DENY%5B%22%E5%90%8C%E6%AD%A5%E6%8B%92%E7%BB%9D%22%5D%0A%20%20ADM%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20ETCD%5B%22%E5%AF%B9%E8%B1%A1%E5%86%99%E5%85%A5%E5%AD%98%E5%82%A8%22%5D%0A%20%20ETCD%20--%3E%20LOOP%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%E6%8C%81%E7%BB%AD%E8%AE%B0%E8%B4%A6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("配额的本质是把集群总额在准入时做会计：允许即预扣、删除即返还，账本本身由控制器维持——又是控制循环。两层账本的张力要说清："),e("strong",null,"配额给的是「有权花」，调度给的是「有地方花」"),E("。段内 request 总额被 quota 顶住，不保证创建的 pod 调度得进去（节点可能装不下）；反过来节点层的超售（上一课）继续存在，段 A 存了钱不等于段 B 抢不到物理容量。跨段的硬手段是优先级：PriorityClass 是集群级的，高优租户的 pod 可以驱逐低优租户的 pod——所以优先级表本身就是租户间的合同，得按组织谈判定，不是技术参数。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：段内 quota 设 requests.cpu 为 20 核，已有 5 个 pod 各声明 3 核，账面已用 15。第 6 个 pod 声明 6 核会在准入时立即被拒（15+6=21 超过 20），声明 5 核则放行（15+5=20）——哪怕这时集群里其实空着 100 核没人用。")],-1)),(A(),s(n,null,{default:t(()=>[B(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20POD%5B%22%E6%96%B0%20Pod%20%E5%A3%B0%E6%98%8E%20request%202%E6%A0%B8%22%5D%20--%3E%20QUOTA%5B%22%E6%AE%B5%E8%B4%A6%E6%9C%AC%3A%20%E5%B7%B2%E7%94%A8%2018%2F20%20%E6%A0%B8%22%5D%0A%20%20QUOTA%20--%3E%7C%22%E9%A2%84%E6%89%A3%E5%90%8E%2020%2F20%22%7C%20OK%5B%22%E5%87%86%E5%85%A5%E9%80%9A%E8%BF%87%22%5D%0A%20%20QUOTA%20--%3E%7C%2220%2B2%20%E8%B6%85%E8%B4%A6%E6%9C%AC%22%7C%20REJ%5B%22%E5%90%8C%E6%AD%A5%E6%8B%92%E7%BB%9D%22%5D%0A%20%20OK%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E6%8C%89%E8%8A%82%E7%82%B9%E7%9C%9F%E5%AE%9E%E4%BD%99%E9%87%8F%E6%89%BE%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20SCHED%20--%3E%7C%22%E6%B2%A1%E6%9C%89%E8%8A%82%E7%82%B9%E8%A3%85%E5%BE%97%E4%B8%8B%202%E6%A0%B8%22%7C%20PENDING%5B%22Pod%20%E5%8D%A1%E5%9C%A8%20Pending%22%5D%0A%20%20SCHED%20--%3E%7C%22%E6%9F%90%E8%8A%82%E7%82%B9%E5%89%A9%E4%BD%99%204%E6%A0%B8%22%7C%20RUN%5B%22%E7%BB%91%E5%AE%9A%E8%8A%82%E7%82%B9%E5%BC%80%E5%A7%8B%E8%BF%90%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>成本归因靠标签聚合而不是 quota：账单要的是实际用量分布，quota 只管上限。授权模型的对偶见 <a href="/cs/dac-mac-rbac">DAC / MAC / RBAC</a>：编排把 RBAC 的作用域做成了树状的段，粒度到对象级要靠角色细写。</p><p><span class="marginnote">易错点：quota 只统计写进对象的数字——没填 resources 的 pod 是 BestEffort，绕过全部 request 记账；不配 LimitRange 补默认值的段，账本永远对不上实际负载。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>namespace 不隔离网络（下一课的题）也不隔离内核（安全边界课程的题）；「按团队建段就安全了」是把行政边界误当信任边界。段的数量本身有成本：过多的小段让 RBAC 与配额的组合爆炸，过少的大段让账目混淆——段的切分应跟组织与预算的边界走，不跟微服务的粒度走。多集群联邦与跨集群调度不在本课程。</p><p><span class="marginnote">常见误区：初学者容易以为建了 namespace，段与段之间就「打不通」了。实际上默认配置下，段 A 的 Pod 仍能直接访问段 B 的 Service IP，一个被盗的段内令牌也改不了别的段——真正的隔离要另配 NetworkPolicy 和节点/集群级方案，namespace 只是让权限和账目「有处可挂」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>namespace 是三重作用域：名字、配额账本、授权范围；它不是安全边界。</li><li>quota 在准入时同步记账：允许即预扣；LimitRange 补默认值才堵住记账漏洞。</li><li>配额管「有权花」，调度管「有地方花」，两层账本互相不能替代。</li><li>优先级是集群级、可跨段驱逐的，优先级表是租户间合同，不是技术参数。</li><li>出处：Kubernetes 官方文档（Namespace、ResourceQuota、LimitRange、RBAC）；RBAC 模型见主干课 DAC/MAC/RBAC。</li></ul>',7))])}const P=i(d,[["render",c]]);export{q as __pageData,P as default};
